"use client";

import { useId, useState } from "react";

export type RingCountdown = {
  startAt: number;
  endAt: number;
  observedAt: number;
};
export const completionName = "Batch complete. All emails sent.";

// Keep the outgoing arc mounted with its last props so its DOM offset is frozen.
export function useRingCompletion(
  complete: boolean,
  countdown?: RingCountdown,
) {
  const [state, setState] = useState({
    complete,
    animate: false,
    countdown,
  });
  if (
    state.complete !== complete ||
    (!complete && state.countdown !== countdown)
  ) {
    const next = {
      complete,
      animate: complete && (state.animate || !state.complete),
      countdown: complete ? state.countdown : countdown,
    };
    setState(next);
    return next;
  }
  return state;
}

export function RingCompletion({
  size,
  radius,
  strokeWidth,
  animate,
}: {
  size: number;
  radius: number;
  strokeWidth: number;
  animate: boolean;
}) {
  const gradientId = useId();
  const innerDiameter = (radius - strokeWidth / 2) * 2;
  return (
    <div
      className={`ring-completion absolute inset-0${animate ? " is-entering" : ""}`}
      role="img"
      aria-label={completionName}
    >
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        className="-rotate-90"
        aria-hidden="true"
      >
        <defs>
          {/* Inverse of the SVG's rotation: visible top-left to bottom-right. */}
          <linearGradient id={gradientId} x1="100%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="var(--completion-ring-start)" />
            <stop offset="100%" stopColor="var(--completion-ring-end)" />
          </linearGradient>
        </defs>
        <circle
          className="completion-ring"
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={`url(#${gradientId})`}
          strokeWidth={strokeWidth}
        />
      </svg>
      <div
        className="completion-inner absolute left-[50%] top-[50%] overflow-hidden rounded-[50%] grid place-items-center"
        style={{ width: innerDiameter, height: innerDiameter }}
        aria-hidden="true"
      >
        <div
          className="completion-ripple absolute [top:calc(50%_-_13px)] left-[50%] rounded-[50%] [border:2px_solid_var(--color-globals-background-78)] opacity-[0]"
          style={{ width: size * 0.45, height: size * 0.45 }}
        />
        <div className="completion-content grid [justify-items:center] gap-2.5 relative">
          <div
            className="completion-badge grid place-items-center rounded-[50%] [background:linear-gradient(_135deg,_var(--color-globals-background-78),_var(--color-globals-background-79))] shadow-[0_6px_20px_var(--color-globals-box-shadow-80)]"
            style={{ width: size * 0.45, height: size * 0.45 }}
          >
            <svg
              className="completion-check"
              width={size * 0.24}
              height={size * 0.24}
              viewBox="0 0 40 40"
              fill="none"
              aria-hidden="true"
            >
              <path
                className="completion-check-path [stroke-dasharray:1] [stroke-dashoffset:0]"
                d="M8 21L16 29L32 12"
                stroke="var(--completion-check-ink)"
                strokeWidth="4"
                strokeLinecap="round"
                strokeLinejoin="round"
                pathLength="1"
              />
            </svg>
          </div>
          <span className="completion-label text-foreground text-[12px] font-extrabold leading-[16px] tracking-[0.16em] font-mono">
            ALL SENT
          </span>
        </div>
      </div>
    </div>
  );
}
